import React, { useState, useEffect } from "react";
import { collection, onSnapshot, query, where, deleteDoc, doc } from "firebase/firestore";
import { db } from "../firebase/config";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { FaUserCircle, FaPlus, FaTrash, FaPen, FaPaw } from "react-icons/fa";
import "../pages/adopter/AdopterDashboard.css"; // We can reuse the Adopter CSS for now

const HomePage = () => {
    const navigate = useNavigate();
    const { user, logout } = useAuth();

    // UI States
    const [showMenu, setShowMenu] = useState(false);
    const [pets, setPets] = useState([]);
    const [loading, setLoading] = useState(true);

    // Filters
    const [search, setSearch] = useState("");
    const [filters, setFilters] = useState({ type: "", age: "" });

    // 1. LOGOUT
    const handleLogout = async () => {
        try {
            await logout();
            navigate("/login");
        } catch (error) {
            console.error("Logout failed:", error);
        }
    };

    // 2. READ DATA (All Available Pets)
    useEffect(() => {
        // Query: Show all pets that are not yet adopted
        const q = query(collection(db, "pets"), where("adopted", "==", false));

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const petsData = snapshot.docs.map((doc) => ({
                id: doc.id,
                ...doc.data(),
            }));
            setPets(petsData);
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    // 3. DELETE PET (Only if you are the owner)
    const handleDelete = async (e, petId) => {
        e.stopPropagation(); // Stop clicking the card redirect
        if (window.confirm("Are you sure? This will remove the listing permanently.")) {
            try {
                await deleteDoc(doc(db, "pets", petId));
            } catch (err) {
                console.error("Error deleting:", err);
            }
        }
    };

    const handleEdit = (e, petId) => {
        e.stopPropagation();
        navigate(`/edit-pet/${petId}`);
    };

    // 4. FILTERING LOGIC
    const filteredPets = pets.filter((pet) => {
        const term = search.toLowerCase();
        const matchSearch =
            pet.name.toLowerCase().includes(term) ||
            pet.breed.toLowerCase().includes(term);
        const matchType = filters.type
            ? pet.type && pet.type.toLowerCase() === filters.type.toLowerCase()
            : true;

        return matchSearch && matchType;
    });

    return (
        <div className="adopter-container">
            {/* --- HEADER --- */}
            <header className="dashboard-header">
                <div className="header-left">
                    <h1 className="title">🐾 PetPal Community</h1>
                    <p className="subtitle">Adopt a friend or help one find a home.</p>
                </div>

                <div className="header-right" style={{ display:'flex', gap:'20px', alignItems:'center' }}>

                    {/* ADD PET BUTTON (Visible to everyone now) */}
                    <button
                        onClick={() => navigate("/add-pet")}
                        style={{
                            padding: '10px 20px',
                            borderRadius: '30px',
                            border: 'none',
                            background: '#34d399',
                            color: 'white',
                            fontWeight: 'bold',
                            cursor: 'pointer',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px',
                            boxShadow: '0 4px 10px rgba(52, 211, 153, 0.3)'
                        }}
                    >
                        <FaPlus /> List a Pet
                    </button>

                    {/* PROFILE */}
                    <div style={{ position: 'relative' }}>
                        <FaUserCircle
                            className="profile-icon"
                            onClick={() => setShowMenu(!showMenu)}
                        />
                        {showMenu && (
                            <div className="profile-dropdown">
                                <p style={{ fontSize: '0.9rem', paddingBottom:'10px' }}>{user?.email}</p>
                                <hr />
                                <button onClick={handleLogout}>Log Out</button>
                            </div>
                        )}
                    </div>
                </div>
            </header>

            {/* --- FILTERS & SEARCH --- */}
            <div className="search-section">
                <input
                    type="text"
                    className="search-input"
                    placeholder="Search pets..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>

            <div className="filters-container">
                <select
                    className="filter-select"
                    value={filters.type}
                    onChange={(e) => setFilters({ ...filters, type: e.target.value })}
                >
                    <option value="">All Animals</option>
                    <option value="Dog">Dogs</option>
                    <option value="Cat">Cats</option>
                    <option value="Other">Others</option>
                </select>
            </div>

            {/* --- GRID --- */}
            <h2 className="section-title">Available Pets ({filteredPets.length})</h2>

            {loading ? <p>Loading...</p> : (
                <div className="cards-container">
                    {filteredPets.map((pet) => {
                        const isOwner = pet.ownerId === user.uid; // Check ownership

                        return (
                            <div
                                key={pet.id}
                                className="pet-card"
                                onClick={() => navigate(`/pet/${pet.id}`)}
                                style={{ position: 'relative' }} // For absolute positioning of badges
                            >
                                {/* MY PET BADGE */}
                                {isOwner && (
                                    <div style={{
                                        position: 'absolute',
                                        top: '10px',
                                        left: '10px',
                                        background: '#3b82f6',
                                        color: 'white',
                                        padding: '5px 10px',
                                        borderRadius: '15px',
                                        fontSize: '0.7rem',
                                        fontWeight: 'bold',
                                        zIndex: 2
                                    }}>
                                        MY LISTING
                                    </div>
                                )}

                                <img
                                    src={pet.image}
                                    className="pet-image"
                                    alt={pet.name}
                                    onError={(e) => {e.target.src = 'https://via.placeholder.com/300?text=No+Image'}}
                                />

                                <div className="pet-info">
                                    <h3>{pet.name}</h3>
                                    <p style={{ color: '#777', fontSize: '0.9rem' }}>
                                        {pet.type} • {pet.breed}
                                    </p>

                                    {/* OWNER ACTIONS */}
                                    {isOwner ? (
                                        <div style={{ marginTop: '15px', display: 'flex', gap: '10px' }}>
                                            <button
                                                onClick={(e) => handleEdit(e, pet.id)}
                                                style={{ flex: 1, padding: '8px', background: '#e2e8f0', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>
                                                <FaPen color="#4a5568"/>
                                            </button>
                                            <button
                                                onClick={(e) => handleDelete(e, pet.id)}
                                                style={{ flex: 1, padding: '8px', background: '#fee2e2',YZ: 'none', borderRadius: '8px', cursor: 'pointer' }}>
                                                <FaTrash color="#ef4444"/>
                                            </button>
                                        </div>
                                    ) : (
                                        <button className="details-btn">View Details</button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
};

export default HomePage;
